		{
			title = "Деяния",
			text = [=[• Он пережил плен в загонах Мертвой Головы.
• Он предложил своим спасителям камень клятвы как залог общего дела.
• Он взялся погасить идола, у которого {link:quilboar}свинобраз{/link}ы сжигали своих пленников.]=],
		},
		{
			title = "Неизвестное",
			text = [=[Нигде не записано, как Белнистраз попал в {link:razorfen-downs}Курганы{/link} и куда он ушел, когда идол погас.]=],
		},
	},
	chapters = {
		{
			title = "Камень клятвы",
			hint = "Поклянитесь помочь освобожденному пленнику.",
			text = [=[Белнистраз дал своим спасителям камень и попросил вернуть его, если они готовы пойти с ним. Они вернули. Опасности он от них не скрывал. Дело впереди трудное, сказал он, но если они не будут отвлекаться от задачи, они смогут одержать верх.]=],
		},
		{
			title = "Идол гаснет",
			hint = "Охраняйте пленника, пока он творит свой ритуал у идола.",
			text = [=[Идол у ворот был чудовищной печью, и Белнистраз мог запечатать его навеки, но ритуал оставил бы его беззащитным. Его спутники сдерживали Мертвую Голову пять долгих минут, пока он вслух отсчитывал время. {link:nak}Нак{/link}онец огни погасли. Его самого уже не было, и там, где он стоял, осталась лишь горящая жаровня. В ее пламени возник {link:ogres}огр{/link}омный красный дракон с широкими крыльями. Его голос, ставший глубже, поблагодарил смертных, которые вернули ему веру в них.]=],
		},
	},
	bonds = {
		{ id = "plaguemaw-the-rotting", name = "Чумобрюх Гниющий", note = "пришел остановить его ритуал" },
