		{
			title = "Значение",
			text = [=[Амненнар дал Плети оплот в {link:kalimdor}Калимдоре{/link}. Через него чума достигает народа, который никогда ее не знал, и война, погубившая {link:lordaeron}Лордерон{/link}, пересекает море. Говорят, что он сражался в рядах Плети в {link:battle-of-mount-hyjal}битве у горы Хиджал{/link} и что затем Король-лич приказал ему остаться и распространять его власть. {link:quilboar}Свинобразы{/link}, согнанные со своих земель, были готовы слушать владыку, который обещал им господство над смертью.]=],
		},
		{
			title = "Деяния",
			text = [=[• Он превратил священный лабиринт {link:quilboar}свинобраз{/link}ов в твердыню нежити.
• Он поднял мертвых Курганов скелетами и иссохшими воинами.
• Он подчинил Мертвую Голову своей воле.]=],
		},
	},
	chapters = {
		{
			title = "Принести Свет",
			hint = "Откликнитесь на призыв архиепископа уничтожить лича.",
			text = [=[В {link:stormwind-city}Штормград{/link}е {link:archbishop-benedictus}архиепископ Бенедикт{/link} узнал, что {link:quilboar}свинобраз{/link}ы тернового лабиринта в Степях заключили договор с {link:scourge}Плеть{/link}ю и что ими правит лич. Он не стал ждать, пока зло разрастется. Он послал воителей {link:holy-light}Свет{/link}а пресечь этот союз в корне.]=],
		},
		{
			title = "Принести конец",
			hint = "Отнесите череп лича в Подгород.",
			text = [=[{link:forsaken}Отрекшиеся{/link} поначалу не считали {link:razorfen-downs}Курганы{/link} угрозой. Более поздние донесения переменили их мнение. {red:andrew-brownell}Эндрю Браунелл{/red} из числа {link:royal-apothecary-society}аптекарей{/link} полагал, что Амненнар связан мыслью с самим повелителем {link:ner-zhul}Нер'зулом{/link} и что эту связь надо разорвать. Он попросил череп лича.]=],
		},
	},
	mentions = {
		{ text = "Сонмище зла: растущие ряды Курганов" },
	},
	bonds = {
		{ id = "belnistrasz", name = "Белнистраз", note = "враг всего, что он строит" },
		{ id = "mordresh-fire-eye", name = "Мордреш Огненный Глаз", note = "его слуга" },
		{ id = "glutton", name = "Обжора", note = "его слуга" },
		{ id = "ambassador-malcin", name = "посол Малсин", note = "такой же слуга Короля-лича" },
	},
})

