Translate("ruRU", "death-s-head", {
	title = "Мертвая Голова",
	aliases = { "племя Мертвой Головы", "культ Мертвой Головы" },
	sections = {
		{
			title = "Обзор",
			text = [=[Мертвая Голова — верховные жрецы {link:quilboar}свинобразов{/link}, хранители могильников Курганов Иглошкурых. Они обратились к {link:scourge}Плети{/link}. Под началом лича {link:amnennar-the-coldbringer}Амненнар{/link}а Хладовея они служат нежизни в святейшем месте своего народа, и многие их воины ходят теперь иссохшими трупами.]=],
		},
		{
			title = "Сделка",
			text = [=[Никто за пределами Курганов не знает всей правды о том, как это началось. {link:scourge}Плеть{/link} прислала посланника, посла {link:ambassador-malcin}Малсин{/link}а, который предложил {link:quilboar}свинобраз{/link}ам {link:burning-steppes}Степи{/link} и больше в обмен на их помощь. {link:varimathras}Вариматас{/link} считает, что старуха из {link:razorfen-kraul}Лабиринтов Иглошкурых{/link} осталась в стороне от сделки. Жрецы Курганов — нет. Некоторые из их племени стали пугающе сильны и носят знаки чумы. Ночная эльфийка {link:myriam-moonsinger}Мириам Лунная Певица{/link} видела, как свинобразы каждый день выползают из теней и вымаливают у посланника еще больше силы.]=],
		},
		{
			title = "Орден",
			text = [=[Жрецы, некроманты, геоманты и культисты Мертвой Головы служат личу рядом с живыми воинами {link:quilboar}свинобраз{/link}ов и плетельщиками терний. Их ряды полнят иссохшие свинобразы, боевые вепри и скелеты. Среди них {link:ragglesnout}Рваное Рыло{/link}, который еще жив, и {link:plaguemaw-the-rotting}Чумобрюх Гниющий{/link}, который уже нет. Их пленников держат в загонах у ворот, а тех, кого не спасли, сжигают и поедают перед идолом.]=],
		},
	},
})
